"use strict";

/*
 * C3 Migration Studio.
 * Every research figure on the Evidence tab is read from data/dashboard_data.json
 * (generated by scripts/summarize_evidence.py --dashboard-json). This file holds
 * no research numbers: the only numeric literals are UI layout values in LAYOUT
 * below, plus 0 and 1 in ordinary logic. tests/test_dashboard_data.py checks this.
 */

/* ===== LAYOUT (UI geometry only; no research results) ===== */
const LAYOUT = {
  chartWidth: 780,
  chartMinWidth: 560,
  labelWidth: 260,
  valueWidth: 170,
  barHeight: 18,
  rowGap: 8,
  groupHeader: 22,
  groupGap: 10,
  padTop: 6,
  textOffset: 13,
  textPad: 8,
  percentScale: 100,
  bytesPerKb: 1024,
  shortHash: 7,
  msPerSecond: 1000,
  secondsPerMinute: 60,
};
/* ===== END LAYOUT ===== */

const SVG_NS = "http://www.w3.org/2000/svg";

// Replace a container's content; nested arrays are flattened and empty entries dropped.
function fill(root, ...children) {
  root.replaceChildren(...children.flat(Infinity).filter((c) => c !== null && c !== undefined && c !== false));
}

function h(tag, attrs, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs || {})) {
    if (value === null || value === undefined || value === false) continue;
    if (key === "class") node.className = value;
    else if (key === "text") node.textContent = value;
    else if (key.startsWith("on")) node.addEventListener(key.slice("on".length), value);
    else node.setAttribute(key, value === true ? "" : value);
  }
  for (const child of children.flat(Infinity)) {
    if (child === null || child === undefined || child === false) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

function svg(tag, attrs, ...children) {
  const node = document.createElementNS(SVG_NS, tag);
  for (const [key, value] of Object.entries(attrs || {})) {
    if (value === null || value === undefined) continue;
    if (key === "text") node.textContent = value;
    else if (key.startsWith("on")) node.addEventListener(key.slice("on".length), value);
    else node.setAttribute(key, value);
  }
  for (const child of children.flat(Infinity)) if (child) node.append(child);
  return node;
}

/* ===== EVIDENCE ===== */
const Evidence = (() => {
  let DATA = null;
  const state = { app: null, section: "overview", sqlFilter: "all", sqlSearch: "" };
  const NOT_MEASURED = "Not yet measured";
  const NOT_APPLICABLE = "Not applicable";
  const SECTIONS = ["overview", "sql", "models", "evaluation", "reports"];
  const APP_SCOPED = new Set(["overview", "sql", "models"]);

  // ---------- data access ----------
  const measurements = (pred) => DATA.measurements.filter(pred);
  const measurement = (app, metric, stage) =>
    DATA.measurements.find((m) => m.app === app && m.metric === metric && (!stage || m.stage === stage)) || null;
  const appLabel = (id) => (id === "all" ? "All applications" : (DATA.apps[id] ? DATA.apps[id].label : id));

  function formatValue(m) {
    if (!m || m.status === "not_measured") return NOT_MEASURED;
    if (m.value === null || m.value === undefined) return NOT_APPLICABLE;
    return m.unit === "percent" ? `${m.value}%` : String(m.value);
  }
  function ratio(m) {
    return m && m.numerator !== null && m.numerator !== undefined && m.denominator !== null && m.denominator !== undefined
      ? `${m.numerator}/${m.denominator}` : "";
  }
  function statusBadge(status) {
    const text = { measured: "measured", derived: "derived", not_measured: "not measured" }[status] || status;
    return h("span", { class: `badge ${status}`, text });
  }
  function stageBadge(m) {
    return h("span", { class: `badge stage-badge ${m.stage}`, text: m.stage_label, title: DATA.stage_definitions[m.stage] || "" });
  }

  // ---------- drawer ----------
  const drawer = () => document.getElementById("detail-drawer");
  function openDrawer(title, ...content) {
    document.getElementById("detail-title").textContent = title;
    const body = document.getElementById("detail-body");
    body.replaceChildren(...content.filter((node) => node !== null && node !== undefined));
    drawer().hidden = false;
    document.getElementById("scrim").hidden = false;
    document.getElementById("detail-close").focus();
  }
  function closeDrawer() {
    drawer().hidden = true;
    document.getElementById("scrim").hidden = true;
  }

  function definitionList(pairs) {
    return h("dl", {}, pairs.filter(([, v]) => v !== null && v !== undefined && v !== "").map(([k, v]) => [
      h("dt", { text: k }), h("dd", {}, v),
    ]));
  }

  function relatedSites(m) {
    const stageSites = DATA.stage_sites[`${m.app}|${m.stage_label}`];
    if (stageSites) {
      const wanted = { recovery_precision: ["FP"], recovery_recall: ["FN"], correct_abstention: ["TN"] }[m.metric];
      const rows = stageSites.filter((s) => !wanted || wanted.includes(s.outcome));
      if (!rows.length) return h("p", { class: "muted", text: "No related sites for this metric at this stage." });
      return h("div", {}, h("h4", { text: "Related sites (from the evaluation file)" }), table(
        ["Ground-truth ID", "Query ID", "PHP site", "Outcome", "C3 status", "Reason code"],
        rows.map((s) => [s.gt_id, s.query_id || "—", h("code", { text: s.site }), s.outcome, s.c3_status || "—", s.reason_code || "—"]),
      ));
    }
    if (m.stage === "current-code" && DATA.records[m.app]) {
      const rows = DATA.records[m.app].filter((r) => r.unresolved_stage);
      if (!rows.length) return h("p", { class: "muted", text: "No unresolved sites for this application in the current-code run." });
      return h("div", {}, h("h4", { text: "Unresolved sites (current-code run)" }), table(
        ["Query ID", "Ground-truth ID", "PHP site", "Stage", "Reason"],
        rows.map((r) => [r.query_id, r.gt_id || "—", h("code", { text: `${r.file}:${r.line}` }), r.unresolved_stage,
          r.unresolved_reason ? `${r.unresolved_reason_code}: ${r.unresolved_reason}` : r.unresolved_reason_code]),
      ));
    }
    return null;
  }

  function showMeasurement(m) {
    const source = m.source || {};
    const fields = source.fields ? Object.entries(source.fields).map(([k, v]) => `${k}: ${v}`).join("; ") : null;
    openDrawer(m.label,
      definitionList([
        ["Application", appLabel(m.app)],
        ["Evaluation stage", stageBadge(m)],
        ["Stage meaning", DATA.stage_definitions[m.stage] || null],
        ["Value", formatValue(m)],
        ["Numerator / denominator", ratio(m) || "—"],
        ["Status", statusBadge(m.status)],
        ["Evidence file", source.file ? h("code", { text: source.file }) : "—"],
        ["Fields", fields],
        ["Derivation", source.derivation || null],
        ["Note", m.note || null],
      ]),
      relatedSites(m));
  }

  // ---------- small builders ----------
  function table(headers, rows, onRow) {
    return h("div", { class: "table-wrap" }, h("table", {},
      h("thead", {}, h("tr", {}, headers.map((x) => h("th", { text: x })))),
      h("tbody", {}, rows.map((cells, i) => h("tr", onRow ? { tabindex: "0", style: "cursor:pointer", onclick: () => onRow(i),
        onkeydown: (e) => { if (e.key === "Enter") onRow(i); } } : {},
        cells.map((c) => h("td", { class: typeof c === "number" ? "num" : null }, c ?? "—"))))),
    ));
  }

  function kpi(m, label, foot) {
    return h("button", {
      type: "button", class: "kpi", style: "text-align:left;cursor:pointer;font:inherit;color:inherit",
      onclick: () => m && showMeasurement(m), "aria-label": `${label}: ${formatValue(m)}`,
    },
    h("div", { class: "kpi-label", text: label }),
    h("div", { class: "kpi-value", text: formatValue(m) }),
    h("div", { class: "kpi-foot" }, m ? [m.stage_label, " · ", statusBadge(m.status)] : NOT_MEASURED, foot ? [" · ", foot] : null));
  }

  function card(title, sub, ...children) {
    return h("div", { class: "card" }, h("h3", { text: title }), sub ? h("p", { class: "sub", text: sub }) : null, children);
  }

  // ---------- charts ----------
  function barChart(items, options = {}) {
    const groups = new Map();
    for (const m of items) {
      const key = options.groupBy ? options.groupBy(m) : m.app;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(m);
    }
    const area = LAYOUT.chartWidth - LAYOUT.labelWidth - LAYOUT.valueWidth;
    const rows = [];
    let y = LAYOUT.padTop;
    for (const [group, members] of groups) {
      rows.push(svg("text", { x: 0, y: y + LAYOUT.textOffset, class: "group-label", text: appLabel(group) }));
      y += LAYOUT.groupHeader;
      for (const m of members) {
        const fraction = m.unit === "percent" ? (m.value ?? 0) / LAYOUT.percentScale
          : (m.denominator ? m.numerator / m.denominator : 0);
        const label = options.label ? options.label(m) : m.stage_label;
        const fill = options.color ? options.color(m) : `var(--stage-${m.stage})`;
        rows.push(svg("g", {
          class: "bar", tabindex: "0", role: "button",
          "aria-label": `${appLabel(m.app)}, ${label}: ${formatValue(m)} ${ratio(m)}`,
          onclick: () => showMeasurement(m),
          onkeydown: (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); showMeasurement(m); } },
        },
        svg("title", { text: `${label}: ${formatValue(m)} ${ratio(m)}` }),
        svg("text", { x: LAYOUT.textPad, y: y + LAYOUT.textOffset, class: "muted", text: label }),
        svg("rect", { class: "track", x: LAYOUT.labelWidth, y, width: area, height: LAYOUT.barHeight, rx: LAYOUT.padTop }),
        svg("rect", { class: "fill", x: LAYOUT.labelWidth, y, width: Math.max(0, fraction * area), height: LAYOUT.barHeight,
          rx: LAYOUT.padTop, style: `fill:${fill}` }),
        svg("text", { x: LAYOUT.labelWidth + area + LAYOUT.textPad, y: y + LAYOUT.textOffset,
          text: `${formatValue(m)}${ratio(m) ? `  (${ratio(m)})` : ""}` })));
        y += LAYOUT.barHeight + LAYOUT.rowGap;
      }
      y += LAYOUT.groupGap;
    }
    return h("div", { class: "chart" }, svg("svg", {
      viewBox: `0 0 ${LAYOUT.chartWidth} ${y}`, style: `min-width:${LAYOUT.chartMinWidth}px`, role: "group",
      "aria-label": options.title || "chart",
    }, rows));
  }

  function stageLegend() {
    return h("div", { class: "legend" }, Object.entries(DATA.stage_definitions).map(([key, text]) =>
      h("span", { style: `--swatch:var(--stage-${key})`, title: text, text: key })));
  }

  function e1Chart() {
    const runs = DATA.experiments.e1.runs;
    const area = LAYOUT.chartWidth - LAYOUT.labelWidth - LAYOUT.valueWidth;
    const colors = { PASS: "var(--good)", FAIL: "var(--bad)", INCONCLUSIVE: "var(--warn)" };
    let y = LAYOUT.padTop;
    const nodes = [];
    for (const run of runs) {
      const final = run.kind === "final";
      nodes.push(svg("text", { x: 0, y: y + LAYOUT.textOffset, class: final ? "group-label" : "muted",
        text: `${appLabel(run.app)} · ${final ? "final run" : "superseded first run"}` }));
      let x = LAYOUT.labelWidth;
      for (const verdict of ["PASS", "FAIL", "INCONCLUSIVE"]) {
        const count = run.verdicts[verdict];
        const width = run.sites ? (count / run.sites) * area : 0;
        const m = final ? measurement(run.app, `e1_${verdict.toLowerCase()}`) : null;
        const open = () => (m ? showMeasurement(m) : openDrawer(`E1 ${verdict} (superseded run)`, definitionList([
          ["Application", appLabel(run.app)], ["Verdict", verdict], ["Sites", `${count}/${run.sites}`],
          ["Evidence file", h("code", { text: run.file })], ["Note", run.note]])));
        nodes.push(svg("g", { class: "bar", tabindex: "0", role: "button", "aria-label": `${verdict} ${count} of ${run.sites}`,
          onclick: open, onkeydown: (e) => { if (e.key === "Enter") open(); } },
        svg("title", { text: `${verdict}: ${count}/${run.sites}` }),
        svg("rect", { x, y, width, height: LAYOUT.barHeight, class: final ? "fill" : "fill superseded", style: `fill:${colors[verdict]}` })));
        x += width;
      }
      nodes.push(svg("text", { x: LAYOUT.labelWidth + area + LAYOUT.textPad, y: y + LAYOUT.textOffset,
        text: `${run.verdicts.PASS} pass · ${run.verdicts.FAIL} fail · ${run.verdicts.INCONCLUSIVE} inconclusive` }));
      y += LAYOUT.barHeight + LAYOUT.groupHeader;
    }
    return h("div", {},
      h("div", { class: "chart" }, svg("svg", { viewBox: `0 0 ${LAYOUT.chartWidth} ${y}`, style: `min-width:${LAYOUT.chartMinWidth}px` }, nodes)),
      h("div", { class: "legend" }, Object.entries(colors).map(([k, c]) => h("span", { style: `--swatch:${c}`, text: k }))));
  }

  // ---------- sections ----------
  function renderOverview(root) {
    const app = DATA.apps[state.app];
    const cur = (metric) => measurement(state.app, metric, "current-code");
    const notes = [];
    if (state.app === "clinic_inventory_legacy_hard") notes.push(DATA.disclosures.clinic.text);
    if (state.app === "fee_rainbow") notes.push(DATA.disclosures.fee_rainbow.text);
    if (state.app === "dignity_dev_hms") notes.push(DATA.disclosures.dignity_dev.text);
    if (app.note) notes.push(app.note);

    fill(root, 
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: `Overview · ${app.label}` }),
        h("p", {}, [h("span", { class: "badge", text: app.role }), " ", app.provenance]))),
      ...notes.map((t) => h("div", { class: "notice", text: t })),
      h("div", { class: "grid kpis" },
        kpi(cur("sql_detected"), "SQL detected"),
        kpi(cur("sql_recovered"), "SQL recovered"),
        kpi(cur("converted_functions"), "Converted functions"),
        kpi(cur("unresolved_total"), "Unresolved sites")),
      h("div", { class: "grid kpis", style: "margin-top:16px" },
        kpi(cur("converted_general"), "Converted by general rules"),
        kpi(cur("converted_template"), "Converted by query-specific templates"),
        kpi(cur("unresolved_recovery"), "Unresolved at recovery"),
        kpi(cur("unresolved_conversion"), "Unresolved at conversion"),
        kpi(cur("manual_review_rate"), "Manual-review rate", "not developer effort")),
      h("p", { class: "muted", text: "Counts are from a fresh run of the current pipeline (stage: current code). "
        + "Recovery accuracy and conversion coverage against ground truth are on the Evaluation tab." }),
      card("All applications (current code)", "Select a row to switch application.", table(
        ["Application", "Role", "Detected", "Recovered", "Converted", "of which templates", "Unresolved"],
        Object.values(DATA.apps).map((a) => [a.label, a.role,
          formatValue(measurement(a.id, "sql_detected", "current-code")),
          formatValue(measurement(a.id, "sql_recovered", "current-code")),
          formatValue(measurement(a.id, "converted_functions", "current-code")),
          formatValue(measurement(a.id, "converted_template", "current-code")),
          formatValue(measurement(a.id, "unresolved_total", "current-code"))]),
        (i) => selectApp(Object.keys(DATA.apps)[i]))),
    );
  }

  function renderSql(root) {
    const records = DATA.records[state.app] || [];
    const filters = {
      all: () => true,
      converted: (r) => r.conversion_status === "CONVERTED",
      template: (r) => r.conversion_rule === "query_specific_template",
      unresolved_recovery: (r) => r.unresolved_stage === "recovery",
      unresolved_conversion: (r) => r.unresolved_stage === "conversion",
    };
    const filterSelect = h("select", { "aria-label": "Filter", onchange: (e) => { state.sqlFilter = e.target.value; render(); } },
      [["all", "All sites"], ["converted", "Converted"], ["template", "Converted by query-specific template"],
        ["unresolved_recovery", "Unresolved at recovery"], ["unresolved_conversion", "Unresolved at conversion"]]
        .map(([v, t]) => h("option", { value: v, selected: v === state.sqlFilter, text: t })));
    const searchBox = h("input", { type: "search", placeholder: "Filter by file, query ID or ground-truth ID", value: state.sqlSearch,
      oninput: (e) => { state.sqlSearch = e.target.value; renderSqlTable(); } });
    const holder = h("div");
    function renderSqlTable() {
      const q = state.sqlSearch.toLowerCase();
      const rows = records.filter(filters[state.sqlFilter]).filter((r) =>
        !q || `${r.file}:${r.line} ${r.query_id} ${r.gt_id || ""}`.toLowerCase().includes(q));
      holder.replaceChildren(rows.length ? table(
        ["Query ID", "Ground-truth ID", "PHP file:line", "Operation", "Recovery", "Conversion", "Unresolved reason", "Ground-truth label"],
        rows.map((r) => [r.query_id, r.gt_id || "—", h("code", { text: `${r.file}:${r.line}` }), r.operation || "—",
          r.recovery_status + (r.via_wrapper ? " (wrapper call)" : ""),
          r.conversion_status === "CONVERTED" ? `CONVERTED (${r.conversion_rule === "query_specific_template" ? "query-specific template" : "general rule"})` : "not converted",
          r.unresolved_stage ? `${r.unresolved_stage}: ${r.unresolved_reason_code}${r.unresolved_reason ? ` — ${r.unresolved_reason}` : ""}${r.join_kind ? ` (${r.join_kind})` : ""}` : "—",
          r.gt_label || "—"])) : h("p", { class: "empty", text: "No sites match this filter." }));
    }
    renderSqlTable();
    fill(root, 
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: `SQL Results · ${DATA.apps[state.app].label}` }),
        h("p", { text: "One row per detected SQL execution site in the current-code run. Query IDs are C3's; ground-truth IDs come from "
          + "the author-verified ground truth, matched by file and line (they can differ). Recovered SQL text is not shown." }))),
      state.app === "hms_kishan0725" ? h("div", { class: "notice", text: "HMS has no licence: reason text is withheld (codes only) and no SQL is shown." }) : null,
      h("div", { class: "controls", style: "margin-bottom:12px" }, h("label", { class: "field" }, "Show", filterSelect),
        h("label", { class: "field" }, "Search", searchBox)),
      holder);
  }

  function renderModels(root) {
    const art = DATA.artifacts[state.app];
    const e2 = DATA.experiments.e2[state.app];
    const e3 = DATA.experiments.e3[state.app];
    const labels = { orm_classes: "ORM classes", core_tables: "Core tables (no primary key)", data_access_functions: "Data-access functions",
      unresolved_stubs: "Unresolved-site stubs", alembic_revisions: "Alembic revisions" };
    fill(root, 
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: `Models & Migration · ${DATA.apps[state.app].label}` }),
        h("p", { text: "Generated artifacts of the current-code run. File contents are not shown." }))),
      h("div", { class: "grid kpis" }, Object.entries(art.counts).map(([k, v]) =>
        h("div", { class: "kpi" }, h("div", { class: "kpi-label", text: labels[k] || k }), h("div", { class: "kpi-value", text: String(v) }),
          h("div", { class: "kpi-foot" }, statusBadge("derived"))))),
      h("p", { class: "muted", text: art.derivation }),
      h("div", { class: "grid two" },
        card("Generated files", "Present in the current-code run output.", table(["File", "Present"],
          Object.entries(art.files).map(([f, ok]) => [h("code", { text: f }), h("span", { class: `badge ${ok ? "good" : "bad"}`, text: ok ? "present" : "missing" })]))),
        card("Schema and migration verification", `E2 schema fidelity (${DATA.experiments.e2_dates.live}) and E3 Alembic round trip on MySQL (${DATA.experiments.e3_dates[state.app]}).`, table(["Check", "Result"], [
          ["E2 offline: original DDL (independent parse) vs C3 schema", e2.A_vs_B],
          ["E2 offline: original DDL vs generated models", e2.A_vs_C],
          ["E2 live: DDL loaded in MySQL and reflected vs models", e2.D_vs_C],
          ["Query-vs-schema drift", e2.query_schema_drift],
          ["Tables / columns in the schema", `${e2.tables} / ${e2.columns}`],
          ["E3 round trip (upgrade, compare, check, downgrade)", e3.verdict],
          ...Object.entries(e3.steps).map(([k, v]) => [`E3 step: ${k}`, v]),
        ]))),
    );
  }

  function renderEvaluation(root) {
    const hist = (metric) => measurements((m) => m.metric === metric && m.stage !== "current-code");
    const cur = (metric) => measurements((m) => m.metric === metric && m.stage === "current-code");
    const e4 = DATA.experiments.e4;
    const tests = DATA.experiments.tests;
    const notMeasured = measurements((m) => m.status === "not_measured");
    const latestColumns = measurements((m) => m.category === "column_use");
    const columnRows = new Map();
    for (const m of latestColumns) {
      const key = `${m.app}|${m.stage_label}`;
      if (!columnRows.has(key)) columnRows.set(key, { app: m.app, stage: m, cells: {} });
      columnRows.get(key).cells[m.metric.replace("column_use_", "")] = m;
    }
    const fields = ["operation", "tables", "read", "write", "filter"];
    const fr6 = DATA.limitations.find((l) => l.fr === "FR6");

    fill(root, 
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: "Evaluation" }),
        h("p", { text: "Each chart is one metric. Bars carry their stage label and exact numerator/denominator; select a bar for the "
          + "evidence file and related sites." }))),
      h("div", { class: "notice info", text: DATA.disclosures.no_overall_score.text }),
      h("div", { class: "notice", text: DATA.disclosures.ground_truth.text }),
      card("Evaluation stages", null, stageLegend(), h("ul", {}, Object.entries(DATA.stage_definitions).map(([k, v]) =>
        h("li", {}, h("strong", { text: k }), ": ", v)))),
      card("SQL detection", "Ground-truth live sites detected by C3 (S15).", barChart(hist("sql_detection"), { title: "SQL detection" })),
      card("Recovery precision", "Correct recoveries / all recoveries (S15; ambiguous sites excluded).",
        barChart(hist("recovery_precision"), { title: "Recovery precision" })),
      card("Recovery recall", "Correct recoveries / recoverable sites (S15; ambiguous sites excluded).",
        barChart(hist("recovery_recall"), { title: "Recovery recall" })),
      card("Correct abstentions", "Non-recoverable sites that C3 detected and flagged instead of guessing. Sites never detected are not counted.",
        barChart(hist("correct_abstention"), { title: "Correct abstentions" })),
      card("Conversion coverage (current code)", "Ground-truth recoverable sites that became data-access functions. This is coverage, not recovery accuracy, and not behavioural equivalence.",
        barChart([...cur("conversion_coverage_gt"), ...cur("general_rule_share")], {
          title: "Conversion coverage",
          label: (m) => (m.metric === "general_rule_share" ? "general rules only (code-derived)" : "recoverable converted"),
        }),
        h("div", { class: "notice", text: DATA.disclosures.clinic.text }),
        h("div", { class: "notice", text: DATA.disclosures.fee_rainbow.text })),
      card("E1 behavioural equivalence on MySQL", "Legacy PHP vs generated function on real MySQL, per SQL site. INCONCLUSIVE is not PASS.",
        e1Chart(),
        h("p", { class: "muted" }, "Not measured: ", measurements((m) => m.metric === "e1_equivalence").map((m) => appLabel(m.app)).join(", "),
          ". Conversion alone does not show equivalence.")),
      h("div", {},
        card("E4 injection negatives", `Recording-session check, ${e4.date_utc} (no database).`,
          barChart(cur("e4_safe_functions"), { title: "E4", label: () => "functions SAFE", color: () => "var(--good)" }),
          table(["Total", "Value"], [
            ["Functions tested", e4.totals.functions], ["SAFE", e4.totals.safe], ["UNSAFE", e4.totals.unsafe],
            ["Hostile cases", e4.totals.hostile_cases], ["Benign calls (derived)", e4.totals.benign_calls],
            ["Rejected cases", e4.totals.rejected], ["Payloads per function", e4.payload_count]]),
          h("h4", { text: "Limits of this check" }), h("ul", {}, e4.limitations.map((t) => h("li", { text: t })))),
        card("E2 schema fidelity and E3 Alembic round trip", `MySQL runs: E2 ${DATA.experiments.e2_dates.live}; E3 per application (see Models & Migration).`,
          barChart(measurements((m) => m.category === "e2" || m.category === "e3"), {
            title: "E2/E3", label: (m) => (m.category === "e2" ? "E2: all schema views MATCH" : "E3: round trip PASS"),
            groupBy: () => "all", color: () => "var(--stage-post-adaptation)" }),
          table(["Application", "E2 A–B", "E2 A–C", "E2 D–C", "E3"], Object.keys(DATA.apps).map((id) => [appLabel(id),
            DATA.experiments.e2[id].A_vs_B, DATA.experiments.e2[id].A_vs_C, DATA.experiments.e2[id].D_vs_C, DATA.experiments.e3[id].verdict])))),
      card("Column-use accuracy", "Per SQL operation, against the ground truth. Select a cell for its source.",
        table(["Application", "Stage", ...fields], [...columnRows.values()].map((row) => [appLabel(row.app), stageBadge(row.stage),
          ...fields.map((f) => { const m = row.cells[f]; return m ? h("button", { type: "button", class: "button",
            onclick: () => showMeasurement(m), text: `${formatValue(m)} ${ratio(m)}` }) : "—"; })]))),
      h("div", { class: "grid two" },
        card("Regression tests (non-MySQL)", tests.summary_line, table(["Result", "Count"],
          measurements((m) => m.category === "tests").map((m) => [m.label, h("button", { type: "button", class: "button",
            onclick: () => showMeasurement(m), text: formatValue(m) })])), h("p", { class: "muted", text: tests.note })),
        card("Not yet measured", "Shown as missing, never as zero.", table(["Measurement", "Application", "Status"],
          notMeasured.map((m) => [m.label, appLabel(m.app), h("span", {}, statusBadge(m.status), " ", NOT_MEASURED)])))),
      card("Known limitations (FR2, FR4, FR6)", null, DATA.limitations.map((l) => h("div", { style: "margin-bottom:12px" },
        h("strong", { text: `${l.fr}: ${l.title}. ` }), l.text, " ", h("span", { class: "muted" }, "Evidence: ", h("code", { text: l.evidence })))),
      table(["Join form", "Application", "Query ID", "Ground-truth ID", "PHP site", "Ground-truth label"],
        fr6.sites.map((s) => [s.join_kind, appLabel(s.app), s.query_id, s.gt_id || "—", h("code", { text: s.site }), s.gt_label || "—"]))),
    );
  }

  function renderReports(root) {
    const g = DATA.generated;
    fill(root, 
      h("div", { class: "section-head" }, h("div", {}, h("h2", { text: "Reports" }),
        h("p", { text: "Verified report files in the repository. Only files served with this dashboard can be downloaded here." }))),
      table(["Report", "Path", "In repository", "Download"], DATA.reports.map((r) => [r.title, h("code", { text: r.path }),
        h("span", { class: `badge ${r.exists ? "good" : "bad"}`, text: r.exists ? "present" : "missing" }),
        r.downloadable && r.href ? h("a", { href: r.href, download: "", text: "Download" }) : h("span", { class: "muted", text: "Not served" })])),
      card("Data generation", null, definitionList([
        ["Generated by", h("code", { text: g.by })], ["Date", g.date], ["Git HEAD", h("code", { text: g.git_head })],
        ["Current-code run", g.current_code_run]])),
    );
  }

  // ---------- shell ----------
  function selectApp(id) {
    state.app = id;
    document.getElementById("app-select").value = id;
    render();
  }

  function render() {
    if (!DATA) return;
    for (const id of SECTIONS) {
      document.getElementById(`section-${id}`).hidden = id !== state.section;
      const tab = document.querySelector(`.sub-tab[data-section="${id}"]`);
      tab.setAttribute("aria-selected", String(id === state.section));
    }
    document.getElementById("app-controls").hidden = !APP_SCOPED.has(state.section);
    const root = document.getElementById(`section-${state.section}`);
    ({ overview: renderOverview, sql: renderSql, models: renderModels, evaluation: renderEvaluation, reports: renderReports })[state.section](root);
  }

  function setSection(section) {
    state.section = SECTIONS.includes(section) ? section : "overview";
    render();
  }

  async function init() {
    const status = document.getElementById("load-status");
    try {
      const response = await fetch("data/dashboard_data.json", { cache: "no-store" });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      DATA = await response.json();
    } catch (error) {
      status.className = "notice error";
      status.textContent = `Could not load data/dashboard_data.json (${error.message}). Serve this folder over HTTP, for example: `
        + "python -m http.server --directory components/c3_data_layer/dashboard";
      return;
    }
    status.hidden = true;
    const select = document.getElementById("app-select");
    select.replaceChildren(...Object.values(DATA.apps).map((a) => h("option", { value: a.id, text: `${a.label} — ${a.role}` })));
    select.addEventListener("change", (e) => selectApp(e.target.value));
    state.app = Object.keys(DATA.apps)[0];
    document.getElementById("footer").textContent =
      `C3 Migration Studio · evidence generated ${DATA.generated.date} at ${DATA.generated.git_head.slice(0, LAYOUT.shortHash)}`;
    document.getElementById("detail-close").addEventListener("click", closeDrawer);
    document.getElementById("scrim").addEventListener("click", closeDrawer);
    document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeDrawer(); });
    render();
  }

  return { init, setSection, closeDrawer };
})();
/* ===== END EVIDENCE ===== */

/* ===== TRY IT (no evidence data) ===== */
const TryIt = (() => {
  // Talks only to the local bridge (server.py, /api/...) and to the recorded
  // sample file. It never reads the evidence data, so benchmark results can never
  // appear as results of an uploaded project, and it never computes a percentage:
  // uploads have no ground truth.
  const API = "/api/";
  const SAMPLE = "data/sample_run.json";
  const $ = (id) => document.getElementById(id);
  const state = { connected: false, busy: false, run: null, source: null, previews: {}, timer: null };

  async function getJson(url, options) {
    const response = await fetch(url, Object.assign({ cache: "no-store" }, options || {}));
    let body = null;
    try { body = await response.json(); } catch (error) { body = null; }
    if (!response.ok) throw new Error((body && body.error) || `Request failed (HTTP ${response.status}).`);
    return body;
  }

  const megabytes = (bytes) => Math.round(bytes / (LAYOUT.bytesPerKb * LAYOUT.bytesPerKb));
  const chosen = (id) => { const input = $(id); return input.files && input.files[0] ? input.files[0] : null; };

  function describe(input, target) {
    const file = input.files && input.files[0];
    target.textContent = file
      ? `${file.name} (${Math.max(1, Math.round(file.size / LAYOUT.bytesPerKb))} KB) selected. It stays on this computer.`
      : "No file selected.";
    updateButton();
  }

  function updateButton() {
    const run = $("run-migration");
    run.textContent = state.connected ? (state.busy ? "Analysing…" : "Analyze & Generate Data Layer") : "Local migration connection pending";
    const ready = state.connected && !state.busy && chosen("php-zip") && chosen("schema-sql");
    run.disabled = !ready;
    run.setAttribute("aria-disabled", String(!ready));
    $("load-sample").disabled = state.busy;
  }

  function showError(message) { $("tryit-error").textContent = message; $("tryit-error").hidden = !message; }

  function progress(message) {
    const box = $("tryit-progress");
    box.textContent = message || "";
    box.hidden = !message;
  }

  function startTimer() {
    const started = Date.now();
    progress("Uploading and running C3 on your project…");
    state.timer = setInterval(() => {
      progress(`Running C3 on your project… ${Math.floor((Date.now() - started) / LAYOUT.msPerSecond)} s elapsed`);
    }, LAYOUT.msPerSecond);
  }
  function stopTimer() { clearInterval(state.timer); state.timer = null; progress(""); }

  function clearResults() {
    state.run = null;
    state.source = null;
    state.previews = {};
    for (const id of ["tryit-detected", "tryit-recovered", "tryit-converted", "tryit-unresolved-count"]) $(id).textContent = "—";
    $("tryit-breakdown").textContent = "No analysis run yet.";
    $("tryit-source").hidden = true;
    fill($("tryit-unresolved"), h("div", { class: "placeholder", text: "Unresolved SQL sites of your project will be listed here." }));
    fill($("tryit-code"), h("div", { class: "placeholder", text: "models.py and data_access.py of your project will be previewed here." }));
    fill($("tryit-download"), h("div", { class: "placeholder", text: "A download of the generated data layer will be offered here after a run." }));
  }

  function render(summary, unresolved, source, note) {
    const c = summary.counts;
    state.run = summary.run_id;
    state.source = source;
    $("tryit-count-label").textContent = summary.label;
    $("tryit-detected").textContent = String(c.sql_detected);
    $("tryit-recovered").textContent = String(c.sql_recovered);
    $("tryit-converted").textContent = String(c.converted_functions);
    $("tryit-unresolved-count").textContent = String(c.unresolved_sites);
    $("tryit-breakdown").textContent = `Converted by general rules: ${c.converted_by_general_rules}; by query-specific templates: `
      + `${c.converted_by_query_specific_template}. Unresolved at recovery: ${c.unresolved_recovery_stage}; at conversion: `
      + `${c.unresolved_conversion_stage}. Upload: ${summary.upload.zip_name} (${summary.upload.php_files} .php files used, `
      + `${summary.upload.files_skipped} other files ignored) with ${summary.upload.schema_name}; C3 ran for ${summary.duration_seconds} s.`;
    const badge = $("tryit-source");
    badge.textContent = source === "live" ? "Live run on this computer" : `Recorded run, not live${note ? ` · ${note}` : ""}`;
    badge.className = `badge ${source === "live" ? "good" : "warn"}`;
    badge.hidden = false;

    const sites = unresolved.sites;
    fill($("tryit-unresolved"), sites.length ? h("div", { class: "table-wrap" }, h("table", {},
      h("thead", {}, h("tr", {}, ["Query ID", "PHP file:line", "Stage", "Reason"].map((x) => h("th", { text: x })))),
      h("tbody", {}, sites.map((s) => h("tr", {},
        h("td", { text: s.query_id }), h("td", {}, h("code", { text: `${s.file}:${s.line}` })), h("td", { text: s.stage }),
        h("td", { text: s.reason ? `${s.reason_code}: ${s.reason}` : (s.reason_code || "—") }))))))
      : h("p", { class: "muted", text: "C3 converted every detected SQL site of this upload; nothing was flagged for review." }));

    fill($("tryit-code"),
      h("div", { class: "code-tabs", role: "tablist" }, ["models.py", "data_access.py"].map((name) =>
        h("button", { type: "button", class: "sub-tab code-tab", role: "tab", "data-file": name, text: name,
          onclick: () => renderPreviewInto(name) }))),
      h("div", { id: "tryit-code-view" }));
    renderPreviewInto("models.py");

    fill($("tryit-download"), source === "live"
      ? [h("a", { class: "button primary", href: `${API}runs/${state.run}/download`, download: "", text: "Download generated outputs (.zip)",
        onclick: () => setTimeout(() => fill($("tryit-download"), h("p", { class: "muted",
          text: "Downloaded. The temporary run folder is deleted after the download; run the analysis again to regenerate it." })), LAYOUT.msPerSecond) }),
        h("p", { class: "muted", text: "Contains models.py, data_access.py, unresolved_queries.json, the reports and the alembic folder." })]
      : h("p", { class: "muted", text: "Download is only available for live runs." }));
  }

  function renderPreviewInto(name) {
    const view = $("tryit-code-view");
    for (const tab of document.querySelectorAll(".code-tab")) tab.setAttribute("aria-selected", String(tab.dataset.file === name));
    const show = (p) => fill(view,
      p.truncated ? h("p", { class: "muted", text: `Preview truncated: showing the first part of ${p.file}. Download the outputs for the full file.` }) : null,
      h("pre", { class: "code-preview" }, h("code", { text: p.text })));
    if (state.previews[name]) return show(state.previews[name]);
    if (state.source !== "live") return fill(view, h("p", { class: "muted", text: "No preview recorded for this file." }));
    fill(view, h("p", { class: "muted", text: `Loading ${name}…` }));
    return getJson(`${API}runs/${state.run}/file/${name}`)
      .then((p) => { state.previews[name] = p; show(p); })
      .catch((error) => fill(view, h("p", { class: "muted", text: error.message })));
  }

  async function analyze() {
    const zip = chosen("php-zip");
    const sql = chosen("schema-sql");
    if (!zip) return showError("Choose the PHP project ZIP first.");
    if (!sql) return showError("Choose the MySQL schema (.sql) file first.");
    showError("");
    clearResults();
    state.busy = true;
    updateButton();
    startTimer();
    const form = new FormData();
    form.append("php_zip", zip, zip.name);
    form.append("schema_sql", sql, sql.name);
    try {
      const summary = await getJson(`${API}analyze`, { method: "POST", body: form });
      const unresolved = await getJson(`${API}runs/${summary.run_id}/unresolved`);
      render(summary, unresolved, "live");
    } catch (error) {
      showError(error.message);
    } finally {
      stopTimer();
      state.busy = false;
      updateButton();
    }
  }

  async function loadSample() {
    showError("");
    clearResults();
    try {
      const sample = await getJson(SAMPLE);
      state.previews = sample.previews || {};
      render(sample.summary, sample.unresolved, "recorded", `${sample.app} · recorded ${sample.recorded_at}`);
    } catch (error) {
      showError(`No recorded sample run is available (${error.message}).`);
    }
  }

  async function connect() {
    try {
      const info = await getJson(`${API}limits`);
      const l = info.limits;
      state.connected = true;
      $("tryit-status").className = "notice info";
      $("tryit-status").textContent = "Connected to the local C3 bridge on this computer. Uploads go only to this computer and are "
        + "processed in a temporary folder outside the repository, which is deleted after the download or after an hour.";
      $("tryit-limits").textContent = `Limits: ZIP up to ${megabytes(l.zip_bytes)} MB and ${l.zip_files} files `
        + `(${megabytes(l.extracted_bytes)} MB extracted); schema up to ${megabytes(l.sql_bytes)} MB; `
        + `${l.timeout_seconds / LAYOUT.secondsPerMinute} minute timeout; one run at a time. Only .php files are used.`;
    } catch (error) {
      state.connected = false;
      $("tryit-status").className = "notice";
      $("tryit-status").textContent = "Local migration connection not available. Start the local server with "
        + "components/c3_data_layer/dashboard/server.py to analyse your own project.";
    }
    updateButton();
  }

  function init() {
    const zip = $("php-zip");
    const sql = $("schema-sql");
    zip.addEventListener("change", () => describe(zip, $("php-zip-name")));
    sql.addEventListener("change", () => describe(sql, $("schema-sql-name")));
    $("run-migration").addEventListener("click", analyze);
    $("load-sample").addEventListener("click", loadSample);
    clearResults();
    updateButton();
    connect();
  }
  return { init };
})();
/* ===== END TRY IT ===== */

/* ===== SHELL: tabs, routing, theme ===== */
(() => {
  const THEME_KEY = "c3-studio-theme";

  function applyTheme(theme) {
    document.documentElement.setAttribute("data-theme", theme);
    const toggle = document.getElementById("theme-toggle");
    toggle.textContent = theme === "dark" ? "Light theme" : "Dark theme";
    toggle.setAttribute("aria-pressed", String(theme === "light"));
  }

  function route() {
    const [tab, section] = (location.hash.replace(/^#\/?/, "") || "evidence/overview").split("/");
    const active = tab === "tryit" ? "tryit" : "evidence";
    for (const button of document.querySelectorAll(".main-tab")) {
      button.setAttribute("aria-selected", String(button.dataset.tab === active));
    }
    document.getElementById("panel-evidence").hidden = active !== "evidence";
    document.getElementById("panel-tryit").hidden = active !== "tryit";
    Evidence.closeDrawer();
    if (active === "evidence") Evidence.setSection(section || "overview");
  }

  let theme = "dark";
  try { theme = localStorage.getItem(THEME_KEY) || "dark"; } catch (error) { theme = "dark"; }
  applyTheme(theme);
  document.getElementById("theme-toggle").addEventListener("click", () => {
    theme = theme === "dark" ? "light" : "dark";
    applyTheme(theme);
    try { localStorage.setItem(THEME_KEY, theme); } catch (error) { /* storage unavailable: theme still applies */ }
  });
  for (const button of document.querySelectorAll(".main-tab")) {
    button.addEventListener("click", () => { location.hash = button.dataset.tab === "tryit" ? "#/tryit" : "#/evidence/overview"; });
  }
  for (const button of document.querySelectorAll(".sub-tab")) {
    button.addEventListener("click", () => { location.hash = `#/evidence/${button.dataset.section}`; });
  }
  window.addEventListener("hashchange", route);
  TryIt.init();
  Evidence.init().then(route);
})();
